SELECT wp_wc_orders.id FROM wp_wc_orders INNER JOIN wp_wc_orders_meta AS meta0 ON ( wp_wc_orders.id = meta0.order_id ) INNER JOIN wp_wc_orders_meta AS meta1 ON ( wp_wc_orders.id = meta1.order_id ) WHERE 1=1 AND (wp_wc_orders.status IN ('wc-pending','wc-processing','wc-on-hold','wc-completed','wc-refunded','wc-checkout-draft')) AND (wp_wc_orders.type IN ('shop_order','shop_order_refund')) AND (((meta0.meta_key = '_m1_marker') OR (meta1.meta_key = '_m2_marker'))) AND wp_wc_orders.id NOT IN (SELECT order_id FROM wp_wc_orders_meta WHERE ((meta_key = '_m1_status' AND meta_value IN ('M1_GO','M1_DONE')) OR (meta_key = '_m2_status' AND meta_value IN ('M2_GO','M2_DONE'))) AND order_id IS NOT NULL) GROUP BY wp_wc_orders.id ORDER BY wp_wc_orders.date_created_gmt DESC LIMIT 0, 20

SELECT COUNT(DISTINCT wp_wc_orders.id) FROM wp_wc_orders INNER JOIN wp_wc_orders_meta AS meta0 ON ( wp_wc_orders.id = meta0.order_id ) INNER JOIN wp_wc_orders_meta AS meta1 ON ( wp_wc_orders.id = meta1.order_id ) WHERE 1=1 AND (wp_wc_orders.status IN ('wc-pending','wc-processing','wc-on-hold','wc-completed','wc-refunded','wc-checkout-draft')) AND (wp_wc_orders.type IN ('shop_order','shop_order_refund')) AND (((meta0.meta_key = '_m1_marker') OR (meta1.meta_key = '_m2_marker'))) AND wp_wc_orders.id NOT IN (SELECT order_id FROM wp_wc_orders_meta WHERE ((meta_key = '_m1_status' AND meta_value IN ('M1_GO','M1_DONE')) OR (meta_key = '_m2_status' AND meta_value IN ('M2_GO','M2_DONE'))) AND order_id IS NOT NULL)
